package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.AuthEventDao;import org.nonfood.oilplants.dao.UserDao;import org.nonfood.oilplants.service.UserService;import java.io.*;
@WebServlet("/profile") public class ProfileServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("profile",new UserDao().findById(WebSupport.user(r).getId()).orElseThrow());WebSupport.view(r,s,"user/profile");}catch(Exception e){WebSupport.error(r,s,e,"个人信息暂时不可用。");}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{UserService svc=new UserService();long id=WebSupport.user(r).getId();if("password".equals(r.getParameter("action"))){svc.updatePassword(id,r.getParameter("oldPassword"),r.getParameter("password"),r.getParameter("confirmPassword"));r.setAttribute("success","密码已更新。");}else if("verifyEmail".equals(r.getParameter("action"))){var user=new UserDao().findById(id).orElseThrow();if(!new org.nonfood.oilplants.service.EmailVerificationService().verifyBoundEmail(user,r.getParameter("emailCode")))throw new IllegalArgumentException("邮箱验证码错误、过期或已使用。");try{new AuthEventDao().log(id,user.getUsername(),"EMAIL_VERIFY_SUCCESS",r.getRemoteAddr());}catch(Exception ignored){}r.setAttribute("success","邮箱验证完成。");}else{svc.updateProfile(id,r.getParameter("displayName"),r.getParameter("email"));r.setAttribute("success","个人资料已保存；如更换邮箱，请完成邮箱验证。");}var u=new UserDao().findById(id).orElseThrow();u.setPasswordHash(null);r.getSession().setAttribute(WebSupport.USER,u);r.setAttribute("profile",u);WebSupport.view(r,s,"user/profile");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}
}
